//! 🧪️ Actual native comparisons retain genuine aliases and one finite bank through every source close.
use super::*;
use semio_framework_value_retained_clone::RetainedCloneSource;
use crate::observe_retirement_allocations as observe;
#[path="../../../🧬️contract/🧪️tests/📥️admission/🦀️.rs"]
mod admit;
fn grant(d:crate::RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn law_work(value:&serde_json::Value)->u128{u128::from(value.as_u64().unwrap())}
fn debit(bank:&mut RetainedCloneGrant,work:u128,p:RetainedCloneProgress){assert!(work<=bank.maximum_items as u128);assert!(p.fits(*bank));bank.maximum_items-=work as usize;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;}
#[test]
fn genuine_string_comparison_preserves_denials_cache_and_actual_source_bank(){
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();let stock=&law["stock"];let mut bank=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:stock["release"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};
 for row in law["cases"].as_array().unwrap(){
  let mut sources=Vec::new();for name in ["left","right"]{let original=row[name].as_str().unwrap().to_owned();let pointer=original.as_ptr();let admitted=admit::admit_owned(original);debit(&mut bank,admitted.work,admitted.progress);let source=admitted.source;assert_eq!(source.borrow().get().as_ptr(),pointer);sources.push(source);}
  let oracle=sources[0].borrow().get().cmp(sources[1].borrow().get());assert_eq!(serde_json::to_value(format!("{oracle:?}")).unwrap(),row["ordering"]);let d=String::bounded_ord_birth_demand();let g=grant(d);for denied in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(turn,heap)=observe(||String::admit_bounded_ord_cursor(denied));assert_eq!(turn.work,law_work(&law["birth"]["deniedWork"]));assert_eq!(heap,(0,0));assert!(turn.result.unwrap().is_none());}let(turn,heap)=observe(||String::admit_bounded_ord_cursor(g));assert_eq!(turn.work,law_work(&law["birth"]["work"]));assert_eq!(heap,(0,0));let work=turn.work;let(mut cursor,p)=turn.result.unwrap().unwrap();debit(&mut bank,work,p);let mut complete=false;
  for _ in 0..law["maximumTurns"].as_u64().unwrap(){let d=cursor.advance_retirement_demands(1).unwrap();let g=grant(d);let(turn,heap)=observe(||crate::retained_clone::effect::run(RetainedCloneGrant{maximum_items:0,..g},|effect|cursor.compare(sources[0].borrow(),sources[1].borrow(),BoundedOrdGrant::default(),effect)));assert_eq!(turn.work,law_work(&law["deniedWork"]));assert_eq!(heap,(0,0));assert!(matches!(turn.result,Ok(BoundedOrdStep::Progress(p))if p==Default::default()));let(turn,heap)=observe(||crate::retained_clone::effect::run(g,|effect|cursor.compare(sources[0].borrow(),sources[1].borrow(),BoundedOrdGrant{maximum_items:1,maximum_bytes:1},effect)));let work=turn.work;assert!(work<=law_work(&law["maximumTurnWork"]),"comparison turn work {work} exceeds the law bound");assert_eq!(heap,(0,0));let step=turn.result.unwrap();let p=if let BoundedOrdStep::Authority(p)=step{p}else{Default::default()};debit(&mut bank,work,p);if let BoundedOrdStep::Complete{ordering,..}=step{assert_eq!(ordering,oracle);complete=true;break}}
  assert!(complete);let(turn,heap)=observe(||crate::retained_clone::effect::run(RetainedCloneGrant::default(),|effect|cursor.compare(sources[0].borrow(),sources[1].borrow(),BoundedOrdGrant::default(),effect)));assert_eq!(turn.work,law_work(&law["cachedWork"]));assert_eq!(heap,(0,0));assert!(matches!(turn.result,Ok(BoundedOrdStep::Complete{ordering,..})if ordering==oracle));
  cursor.begin_close();for _ in 0..law["maximumTurns"].as_u64().unwrap(){if cursor.terminal_is_empty(){break}let g=grant(cursor.close_demands(1).unwrap());let(turn,heap)=observe(||crate::retained_clone::effect::settle(g,|effect|cursor.close_step(effect)));let work=turn.work;let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(&mut bank,work,p);}assert!(cursor.terminal_is_empty());assert_eq!(observe(||drop(cursor)).1,(0,0));
  for source in &mut sources{for _ in 0..law["maximumTurns"].as_u64().unwrap(){if source.terminal_is_empty(){break}let g=grant(source.next_close_demand(1).unwrap());let turn=crate::retained_clone::effect::settle(g,|effect|source.close_step(effect));let work=turn.work;let p=turn.result.unwrap().progress();debit(&mut bank,work,p);}assert!(source.terminal_is_empty());}
 }
}
